const q=(s,c=document)=>c.querySelector(s),qa=(s,c=document)=>[...c.querySelectorAll(s)];
const inventory=(window.CHASER_VEHICLES||[]).filter(v=>['published','sold'].includes(v.publicationStatus));
const money=n=>n==null?'Enquire':`US$${Number(n).toLocaleString('en-US')}`;
const number=n=>n==null?'—':Number(n).toLocaleString('en-US');
const vehicleName=v=>`${v.listingYear||v.year||''} ${v.make} ${v.model}${v.trim?` ${v.trim}`:''}`.trim();
const detailUrl=v=>`cars/${v.slug}`;
const waMessage=v=>`Hello Chaser Motors, I'm interested in the ${vehicleName(v)} listed at ${money(v.price)}. Please send me more information.`;
const whatsapp=v=>`https://wa.me/263788265454?text=${encodeURIComponent(waMessage(v))}`;
let state={query:'',make:'all',body:'all',year:'all',price:'all',fuel:'all',transmission:'all',status:'all',sort:'recent'};
let saved=new Set(JSON.parse(localStorage.getItem('chaser-saved')||'[]'));
let compared=new Set(JSON.parse(localStorage.getItem('chaser-compare')||'[]'));

const nav=q('.nav-shell'),menuBtn=q('.menu-btn'),sheet=q('.mobile-sheet');
addEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>30),{passive:true});
if(menuBtn){menuBtn.addEventListener('click',()=>{const open=sheet.classList.toggle('open');menuBtn.setAttribute('aria-expanded',open);menuBtn.textContent=open?'CLOSE':'MENU'});qa('a',sheet).forEach(a=>a.addEventListener('click',()=>{sheet.classList.remove('open');menuBtn.setAttribute('aria-expanded','false');menuBtn.textContent='MENU'}));}

const section=q('#cars'),legacyFilters=q('.filters',section),grid=q('.vehicle-grid',section),stockNote=q('.stock-note',section);
if(legacyFilters)legacyFilters.outerHTML=`<div class="inventory-tools reveal"><label class="vehicle-search"><span>SEARCH</span><input id="vehicle-search" type="search" placeholder="Toyota, Hilux, Hybrid…" autocomplete="off"></label><button class="filter-open secondary-action" type="button">FILTERS <span>＋</span></button><div class="filter-rail" aria-label="Vehicle filters"></div><label class="sort-control"><span>SORT</span><select id="vehicle-sort"><option value="recent">Recently added</option><option value="price-asc">Price low → high</option><option value="price-desc">Price high → low</option><option value="year-desc">Newest year</option><option value="mileage-asc">Lowest mileage</option></select></label><button class="secondary-action saved-open" type="button"><span>♡</span> SAVED <b>${saved.size}</b></button></div>`;
if(stockNote)stockNote.outerHTML=`<div class="inventory-meta"><p id="result-count" aria-live="polite"></p><p>Vehicle details and availability are supplied by Chaser Motors and may change.</p></div><div class="empty-inventory" hidden><p class="eyebrow">No matches yet</p><h3>Tell us what you’re looking for and Chaser can source it.</h3><button class="split-action find-car-open"><span>FIND MY CAR</span><i>↗</i></button></div>`;

function options(key,label){const vals=[...new Set(inventory.map(v=>v[key]).filter(Boolean))].sort((a,b)=>typeof a==='number'?b-a:String(a).localeCompare(String(b)));return `<label><span>${label}</span><select data-filter="${key}"><option value="all">All</option>${vals.map(v=>`<option>${v}</option>`).join('')}</select></label>`}
q('.filter-rail').innerHTML=options('make','Make')+options('bodyClass','Body class')+options('year','Year')+`<label><span>Price</span><select data-filter="price"><option value="all">All</option><option value="under-7000">Under US$7,000</option><option value="7000-10000">US$7,000–10,000</option><option value="over-10000">Over US$10,000</option></select></label>`+options('fuel','Fuel')+options('transmission','Transmission')+options('status','Status');
function priceMarkup(v){if(v.inspectionPrice&&v.noInspectionPrice)return `<div class="dual-price"><div><strong>${money(v.inspectionPrice)}</strong><span>${v.make==='Honda'?'CIF · ':''}With inspection <button class="info-tip" aria-label="Inspection pricing information" data-tip="Inspection pricing includes the inspection stated by Chaser Motors.">ⓘ</button></span></div><div><strong>${money(v.noInspectionPrice)}</strong><span>${v.make==='Honda'?'C&F · ':''}Without inspection <button class="info-tip" aria-label="C and F pricing information" data-tip="C&F means cost and freight. Confirm final charges with Chaser Motors.">ⓘ</button></span></div></div>`;return `<div class="single-price"><strong>${money(v.price)}</strong><span>${v.pricingNote||''}</span></div>`}
function card(v){const feats=[v.fuel,v.transmission,...v.features].filter(Boolean).slice(0,4);return `<article class="vehicle-card inventory-card" data-id="${v.id}"><div class="vehicle-image"><img src="${v.thumbnail}" alt="${vehicleName(v)}" loading="lazy" width="800" height="560">${v.images.length>1?`<img class="alternate-angle" src="${v.images[1]}" alt="${vehicleName(v)} alternate angle" loading="lazy" width="800" height="560">`:''}${v.offerLabel?`<span class="offer-tag">${v.offerLabel}</span>`:''}${v.videos.length?`<button class="video-chip" data-video="${v.id}">▶ WALKAROUND</button>`:''}<div class="card-hover-actions"><button class="quick-view" data-quick="${v.id}">QUICK VIEW</button></div></div><div class="vehicle-info"><div class="status-line"><span>${v.bodyClass}</span><span class="status-dot">${v.status}</span></div><h3>${vehicleName(v)}</h3><div class="card-specs">${feats.map(f=>`<span>${f}</span>`).join('')}${v.features.length>2?`<span>+${Math.max(0,v.features.length-2)} more</span>`:''}</div>${priceMarkup(v)}<div class="card-actions"><a class="split-action" href="${detailUrl(v)}"><span>VIEW THIS CAR</span><i>↗</i></a><button class="secondary-action enquire-open" data-enquire="${v.id}"><span>＋</span> ASK ABOUT</button><button class="icon-action save-car ${saved.has(v.id)?'active':''}" data-save="${v.id}" aria-label="${saved.has(v.id)?'Remove from':'Save to'} shortlist" aria-pressed="${saved.has(v.id)}">${saved.has(v.id)?'♥':'♡'}</button><button class="icon-action compare-car ${compared.has(v.id)?'active':''}" data-compare="${v.id}" aria-label="Compare ${vehicleName(v)}" aria-pressed="${compared.has(v.id)}">＋</button></div></div></article>`}
function filtered(){let list=inventory.filter(v=>{const hay=[v.make,v.model,v.trim,v.fuel,v.bodyClass,...v.features].filter(Boolean).join(' ').toLowerCase(),priceOk=state.price==='all'||(state.price==='under-7000'&&v.price<7000)||(state.price==='7000-10000'&&v.price>=7000&&v.price<=10000)||(state.price==='over-10000'&&v.price>10000);return(!state.query||hay.includes(state.query))&&priceOk&&(state.make==='all'||v.make===state.make)&&(state.body==='all'||v.bodyClass===state.body)&&(state.year==='all'||String(v.year)===state.year)&&(state.fuel==='all'||v.fuel===state.fuel)&&(state.transmission==='all'||v.transmission===state.transmission)&&(state.status==='all'||v.status===state.status)});const sorts={recent:(a,b)=>b.createdAt.localeCompare(a.createdAt),'price-asc':(a,b)=>(a.price??Infinity)-(b.price??Infinity),'price-desc':(a,b)=>(b.price??-1)-(a.price??-1),'year-desc':(a,b)=>(b.year??0)-(a.year??0),'mileage-asc':(a,b)=>(a.mileageKm??Infinity)-(b.mileageKm??Infinity)};return list.sort(sorts[state.sort])}
function render(){grid.classList.add('inventory-updating');setTimeout(()=>{const list=filtered();grid.innerHTML=list.map(card).join('');grid.classList.remove('inventory-updating');q('#result-count').textContent=`Showing ${list.length} published vehicle${list.length===1?'':'s'}`;q('.empty-inventory').hidden=!!list.length;bindInventory()},180)}
function bindInventory(){qa('[data-quick]').forEach(b=>b.onclick=()=>openQuick(b.dataset.quick));qa('[data-video]').forEach(b=>b.onclick=()=>openVideo(b.dataset.video));qa('[data-enquire]').forEach(b=>b.onclick=()=>openEnquiry(b.dataset.enquire));qa('[data-save]').forEach(b=>b.onclick=()=>toggleSave(b.dataset.save));qa('[data-compare]').forEach(b=>b.onclick=()=>toggleCompare(b.dataset.compare));qa('.info-tip').forEach(b=>b.onclick=e=>{e.stopPropagation();showToast(b.dataset.tip)});magnetic()}
q('#vehicle-search').addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();render()});q('#vehicle-sort').addEventListener('change',e=>{state.sort=e.target.value;render()});qa('[data-filter]').forEach(s=>s.addEventListener('change',e=>{const map={bodyClass:'body'};state[map[e.target.dataset.filter]||e.target.dataset.filter]=e.target.value;render()}));

function ensureLayers(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-layer" aria-hidden="true"><div class="modal-scrim"></div><div class="modal-panel" role="dialog" aria-modal="true"><button class="modal-close" aria-label="Close">×</button><div class="modal-content"></div></div></div><aside class="saved-drawer" aria-hidden="true"><button class="drawer-close" aria-label="Close saved cars">×</button><p class="eyebrow">Your shortlist</p><h2>Saved cars</h2><div class="saved-list"></div></aside><div class="drawer-scrim"></div><div class="compare-tray" hidden><span>COMPARE <b>0</b> VEHICLES</span><button class="split-action compare-open"><span>COMPARE NOW</span><i>↗</i></button></div><div class="toast" role="status" aria-live="polite"></div>`);q('.modal-close').onclick=closeModal;q('.modal-scrim').onclick=closeModal;q('.drawer-close').onclick=closeDrawer;q('.drawer-scrim').onclick=closeDrawer;q('.saved-open').onclick=openSaved;q('.compare-open').onclick=openCompare;q('.filter-open').onclick=openFilters;q('.find-car-open').onclick=openFinder;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeDrawer()}});updateTray()}
function openModal(html,type=''){q('.modal-content').innerHTML=html;q('.modal-panel').className=`modal-panel ${type}`;q('.modal-layer').classList.add('open');q('.modal-layer').setAttribute('aria-hidden','false');document.body.classList.add('locked');q('.modal-close').focus()}
function closeModal(){q('.modal-layer')?.classList.remove('open');q('.modal-layer')?.setAttribute('aria-hidden','true');document.body.classList.remove('locked')}
const findVehicle=id=>inventory.find(v=>v.id===id);
const specs=v=>[["Year",v.month?`${v.year}/${v.month}`:v.year],["Mileage",v.mileageKm?`${number(v.mileageKm)} km`:null],["Engine",v.engineCc?`${number(v.engineCc)}cc`:null],["Transmission",v.transmission],["Fuel",v.fuel]].filter(x=>x[1]);
function openQuick(id){const v=findVehicle(id);openModal(`<div class="quick-grid"><div class="quick-image"><img src="${v.featuredImage}" alt="${vehicleName(v)}"></div><div><p class="eyebrow">Quick view · ${v.status}</p><h2>${vehicleName(v)}</h2>${priceMarkup(v)}<div class="quick-specs">${specs(v).map(([k,val])=>`<div><span>${k}</span><strong>${val}</strong></div>`).join('')}</div><div class="feature-preview">${v.features.slice(0,5).map(f=>`<span>✓ ${f}</span>`).join('')}${v.features.length>5?`<span>+${v.features.length-5} more</span>`:''}</div><div class="quick-actions"><a class="split-action" href="${detailUrl(v)}"><span>VIEW FULL DETAILS</span><i>↗</i></a><a class="secondary-action" href="${whatsapp(v)}"><span>＋</span> ASK ON WHATSAPP</a></div></div></div>`,'quick-modal')}
function openVideo(id){const v=findVehicle(id),media=v?.videos?.[0];if(!media)return showToast('A vehicle video has not been added yet.');const isEmbed=/youtube\.com|youtu\.be|vimeo\.com/.test(media.url);const player=isEmbed?`<iframe src="${media.url}" title="${media.type||'Vehicle video'}" allow="fullscreen" loading="lazy"></iframe>`:`<video controls preload="metadata" poster="${media.poster||v.featuredImage}"><source src="${media.url}"></video>`;openModal(`<div class="video-modal"><div class="video-frame">${player}</div><p class="eyebrow">${media.type||'Vehicle video'}</p><h2>${vehicleName(v)}</h2><p>${v.year||''} · ${v.engineCc?`${number(v.engineCc)}cc · `:''}${v.transmission||''}</p><button class="secondary-action video-enquire"><span>＋</span> ASK ABOUT THIS VEHICLE</button></div>`,'video-modal');q('.video-enquire').onclick=()=>openEnquiry(v.id)}
function openEnquiry(id){const v=findVehicle(id);openModal(`<div class="enquiry-panel"><p class="eyebrow">Vehicle enquiry</p><h2>Ask about this car</h2><p>${vehicleName(v)}</p><form id="enquiry-form"><label>Name<input name="name" required autocomplete="name"></label><label>WhatsApp number<input name="phone" type="tel" required autocomplete="tel"></label><label>Message<textarea name="message">${waMessage(v)}</textarea></label><button class="split-action" type="submit"><span>SEND ON WHATSAPP</span><i>↗</i></button><a class="secondary-action" href="tel:+263788265454"><span>＋</span> CALL CHASER</a></form></div>`,'enquiry-modal');q('#enquiry-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);location.href=`https://wa.me/263788265454?text=${encodeURIComponent(`${d.get('message')}\n\nName: ${d.get('name')}\nWhatsApp: ${d.get('phone')}`)}`}}
function toggleSave(id){saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem('chaser-saved',JSON.stringify([...saved]));q('.saved-open b').textContent=saved.size;showToast(saved.has(id)?'Vehicle saved to your shortlist.':'Vehicle removed from shortlist.');render()}
function openSaved(){q('.saved-list').innerHTML=saved.size?[...saved].map(id=>{const v=findVehicle(id);return v?`<article><img src="${v.thumbnail}" alt=""><div><strong>${vehicleName(v)}</strong><span>${money(v.price)}</span><a href="${detailUrl(v)}">View car ↗</a></div></article>`:''}).join(''):'<p>No saved vehicles yet. Use the heart control on any vehicle.</p>';q('.saved-drawer').classList.add('open');q('.drawer-scrim').classList.add('open');q('.saved-drawer').setAttribute('aria-hidden','false')}
function closeDrawer(){q('.saved-drawer')?.classList.remove('open');q('.drawer-scrim')?.classList.remove('open');q('.saved-drawer')?.setAttribute('aria-hidden','true')}
function toggleCompare(id){if(compared.has(id))compared.delete(id);else if(compared.size<3)compared.add(id);else return showToast('Compare up to 3 vehicles. Remove one to add another.');localStorage.setItem('chaser-compare',JSON.stringify([...compared]));updateTray();render()}
function updateTray(){const tray=q('.compare-tray');tray.hidden=compared.size<2;q('b',tray).textContent=compared.size}
function openCompare(){const list=[...compared].map(findVehicle).filter(Boolean);const rows=[['Price',v=>money(v.price)],['Year',v=>v.year||'—'],['Mileage',v=>v.mileageKm?`${number(v.mileageKm)} km`:'—'],['Engine',v=>v.engineCc?`${number(v.engineCc)}cc`:'—'],['Transmission',v=>v.transmission||'—'],['Fuel',v=>v.fuel||'—'],['Inspection',v=>v.inspectionPrice?'Available':'Not stated'],['Features',v=>v.features.length?v.features.slice(0,4).join(', '):'Not supplied']];openModal(`<div class="compare-modal"><p class="eyebrow">Side-by-side</p><h2>Compare vehicles</h2><div class="compare-table"><div class="compare-row compare-head"><b>Field</b>${list.map(v=>`<strong>${v.make}<br>${v.model}</strong>`).join('')}</div>${rows.map(([label,get])=>`<div class="compare-row"><b>${label}</b>${list.map(v=>`<span>${get(v)}</span>`).join('')}</div>`).join('')}</div></div>`,'compare-modal')}
function openFilters(){openModal(`<div class="mobile-filters"><p class="eyebrow">Refine inventory</p><h2>Filters</h2>${q('.filter-rail').innerHTML}<button class="split-action apply-filters"><span>SHOW RESULTS</span><i>↗</i></button></div>`,'filter-modal');qa('[data-filter]',q('.modal-content')).forEach(s=>{const key=s.dataset.filter,map={bodyClass:'body'};s.value=state[map[key]||key];s.onchange=e=>state[map[key]||key]=e.target.value});q('.apply-filters').onclick=()=>{render();closeModal()}}
function openFinder(){let step=1,data={};const draw=()=>{const fields=[`<label>Make<input name="make" required></label><label>Model<input name="model"></label>`,`<label>Body class<select name="body"><option>SUV</option><option>Sedan</option><option>Pickup</option><option>Hatchback</option><option>Van</option><option>Other</option></select></label>`,`<label>Budget<input name="budget" required placeholder="e.g. US$10,000"></label>`,`<label>Preferred year<input name="year" placeholder="Optional"></label>`,`<label>Name<input name="name" required autocomplete="name"></label><label>WhatsApp<input name="phone" type="tel" required autocomplete="tel"></label>`];openModal(`<form class="finder" id="finder-form"><p class="eyebrow">Find my car</p><div class="finder-progress"><b>0${step}</b><i style="width:${step*20}%"></i><span>05</span></div><h2>${['What are you looking for?','Choose a body class','Set your budget','Preferred year','Where can we reach you?'][step-1]}</h2>${fields[step-1]}<div class="finder-nav">${step>1?'<button type="button" class="secondary-action finder-back"><span>←</span> BACK</button>':''}<button class="split-action" type="submit"><span>${step===5?'SEND REQUEST':'CONTINUE'}</span><i>↗</i></button></div></form>`,'finder-modal');q('.finder-back')?.addEventListener('click',()=>{step--;draw()});q('#finder-form').onsubmit=e=>{e.preventDefault();Object.assign(data,Object.fromEntries(new FormData(e.target)));if(step<5){step++;draw()}else location.href=`https://wa.me/263788265454?text=${encodeURIComponent(`Hello Chaser Motors, please help me find a car.\nMake: ${data.make}\nModel: ${data.model||'Any'}\nBody class: ${data.body}\nBudget: ${data.budget}\nPreferred year: ${data.year||'Flexible'}\nName: ${data.name}\nWhatsApp: ${data.phone}`)}`}};draw()}
function showToast(text){const t=q('.toast');t.textContent=text;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3600)}
function magnetic(){if(!matchMedia('(hover:hover) and (pointer:fine)').matches)return;qa('.split-action').forEach(b=>{b.onpointermove=e=>{const r=b.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)*.08,y=(e.clientY-r.top-r.height/2)*.08;b.style.transform=`translate(${Math.max(-5,Math.min(5,x))}px,${Math.max(-4,Math.min(4,y))}px)`};b.onpointerleave=()=>b.style.transform=''})}
const reveal=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target)}}),{threshold:.1});qa('.reveal').forEach((el,i)=>{el.style.transitionDelay=`${Math.min((i%5)*80,320)}ms`;reveal.observe(el)});
const sections=qa('main section[id]'),links=qa('.nav-links a'),navLinks=q('.nav-links');function traceNav(){const a=q('.nav-links a.active');if(!a||!navLinks)return;const p=navLinks.getBoundingClientRect(),r=a.getBoundingClientRect();navLinks.style.setProperty('--trace-x',`${r.left-p.left}px`);navLinks.style.setProperty('--trace-w',`${r.width}px`)}const spy=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${e.target.id}`));traceNav()}}),{rootMargin:'-38% 0px -56%'});sections.forEach(s=>spy.observe(s));addEventListener('resize',traceNav);traceNav();
q('#request-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);location.href=`https://wa.me/263788265454?text=${encodeURIComponent(`Hello Chaser Motors, I would like to request a vehicle.\nName: ${d.get('name')}\nPhone: ${d.get('phone')}\nMake: ${d.get('make')||'Not specified'}\nModel: ${d.get('model')||'Not specified'}\nBudget: ${d.get('budget')||'Not specified'}\nBody type: ${d.get('body')}\nYear: ${d.get('year')||'Flexible'}\nNotes: ${d.get('notes')||'None'}`)}`});
ensureLayers();qa('.nav-actions .btn-blue,.sheet-actions .btn-blue').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openFinder()}));render();magnetic();
